import{z as i,x as A,o as e,c as n,q as l,j as B,D as E,d as o,s,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"成本-质量曲线","description":"","frontmatter":{"title":"成本-质量曲线","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-cost-quality-curve.md","filePath":"llm/dec-cost-quality-curve.md","lastUpdated":1791413859000}'),d={name:"llm/dec-cost-quality-curve.md"};function m(p,a,c,C,h,f){const t=A("Mermaid");return e(),n("div",null,[a[2]||(a[2]=l('<h1 id="成本-质量曲线" tabindex="-1">成本-质量曲线 <a class="header-anchor" href="#成本-质量曲线" aria-label="Permalink to &quot;成本-质量曲线&quot;">​</a></h1><div class="epigraph"><p>每个旋钮都能讲一个「更好」的故事；把横轴换成每请求成本、纵轴钉死一种质量度量，故事才会互相可比。</p><footer>—— 据 Snell et al., 2024 的测试时计算权衡与 Pope et al., 2022 的服务成本口径整理</footer></div><p><a href="/llm/dec-bestofn-serving">上一课</a>把 \\(N\\) 的账算清。本课程至此积累了一排旋钮：采样参数、logit bias、文法掩码、判别器引导、Best-of-N、投机、瀑布与并发。本课把它们放上同一条坐标：横轴每请求成本，纵轴质量。成本的分母基础课已给：<a href="/llm/serving-cost-model">服务成本模型</a>的 \\(C_{\\mathrm{tok}}\\)。本课给曲线本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个旋钮在自己的论文与课程里都「有效」，但度量互不可比：核采样报生成质量的人评，文法约束报可解析率，Best-of-N 报真值准确率，投机报加速比。没有统一坐标，团队会在错误的地方优化——为免费旋钮写三周代码，为昂贵旋钮拍脑袋定档。更隐蔽的是漏账：文法的编译与逐步掩码、CFG 的双倍前向、BoN 的打分器与重试、后处理的修复率，都不在「token 数」里。缺口是两张表：每个旋钮的成本倍率表，与一种钉死的质量度量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>成本写成相对倍率</strong>（decode 步的每请求成本，以无约束采样为 \\(1\\times\\)）：</p><ul><li>温度与核采样：\\(1\\times\\)，免费但改变分布形状（<a href="/llm/sampling-temperature-topp">温度课</a>）。</li><li>logit bias 与惩罚：\\(1\\times\\) 加稀疏操作的零头（<a href="/llm/logit-bias">bias 课</a>）。</li><li>文法掩码：约 \\(1\\times\\) 加掩码开销，确定边跳过前向后可 \\(\\lt 1\\times\\)（<a href="/llm/dec-schema-compile">编译与缓存</a>把开销压到查表）。</li><li>判别器引导：一到数倍（<a href="/llm/dec-controlled-advanced">进阶课</a>的账单）。</li><li>Best-of-N：约 \\(N\\times\\)，前缀共享与瀑布打折（<a href="/llm/dec-bestofn-serving">服务化课</a>）。</li><li>投机解码：\\(\\lt 1\\times\\)，折扣即接受率（<a href="/llm/spec-map">投机收束</a>）。<span class="marginnote">直觉类比：投机解码像实习生先起草、老编辑逐段抽查——草稿便宜（小模型），抽查通过就整段收货，不通过才重写。接受率越高，「折扣」越大，所以它能做到比 \\(1\\times\\) 还便宜——这是表里少有的能往左走的旋钮之一（文法掩码的确定边跳步是另一个）。</span></li></ul><p><strong>质量度量钉死一种</strong>：可执行验收（单测、答案比对）\\(\\gt\\) RM 分 \\(\\gt\\) 人工抽样。同一张图只用一种；换度量重画曲线，不拼接。</p><p><strong>扫档位、报边际</strong>：每旋钮 3-5 档，报「边际质量 / 边际成本」，而不是只报最优点的绝对值。</p>',10)),(e(),B(r,null,{default:E(()=>[s(t,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20KNOBS%5B%22%E6%97%8B%E9%92%AE%E9%9B%86%22%5D%20--%3E%20MULT%5B%22%E6%88%90%E6%9C%AC%E5%80%8D%E7%8E%87%E8%A1%A8%EF%BC%9A%E7%9B%B8%E5%AF%B9%201%C3%97%22%5D%0A%20%20KNOBS%20--%3E%20MET%5B%22%E8%B4%A8%E9%87%8F%E5%BA%A6%E9%87%8F%E9%92%89%E6%AD%BB%E4%B8%80%E7%A7%8D%22%5D%0A%20%20MULT%20--%3E%20SWEEP%5B%22%E5%88%86%E6%A1%A3%E6%89%AB%E6%8F%8F%22%5D%0A%20%20MET%20--%3E%20SWEEP%0A%20%20SWEEP%20--%3E%20CURVE%5B%22%E6%88%90%E6%9C%AC-%E8%B4%A8%E9%87%8F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20BUCKET%7B%22%E6%8C%89%E6%B5%81%E9%87%8F%E5%88%86%E6%A1%B6%22%7D%0A%20%20BUCKET%20--%3E%20SLO%5B%22SLO%20%E5%8F%AF%E8%A1%8C%E5%9F%9F%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20SLO%20--%3E%20OP%5B%22%E6%AF%8F%E6%A1%B6%E5%B7%A5%E4%BD%9C%E7%82%B9%EF%BC%9A%E9%A2%84%E7%AE%97%E5%88%B0%E6%A1%A3%E4%BD%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>曲线形状由边际递减决定，且每个旋钮的递减点不同：BoN 在 \\(p\\) 接近 1 的桶上 \\(N\\gt 4\\) 几乎无收益（<a href="/llm/best-of-n">Best-of-N 课</a>的饱和）；过紧掩码存在质量悬崖——合法集缩到只剩骨架时质量跳水（<a href="/llm/grammar-decode">文法课</a>）；CFG 外推过线后质量掉出流形（<a href="/llm/cfg-llm">CFG 课</a>）。<strong>曲线的工程用法是分桶选工作点</strong>：工具调用流量上文法是必选项（不是质量旋钮而是可用性旋钮），它的曲线起点就不在 \\(0\\)；闲聊流量上文法无用，温度与 bias 是全部。SLO 把曲线切成可行域：TPOT 上界砍掉重引导这类慢旋钮，尾延迟预算砍掉深瀑布；可行域内再按边际选点（<a href="/llm/sch-slo-tiers">SLO 分层</a>的成员边界归调度课程，这里只取它的约束面）。</p>',2)),(e(),B(r,null,{default:E(()=>[s(t,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BON%5B%22BoN%EF%BC%9A%E9%A5%B1%E5%92%8C%E5%9E%8B%22%5D%0A%20%20%20%20B1%5B%22N%20%E5%8A%A0%E5%A4%A7%22%5D%20--%3E%20B2%5B%22p%20%E9%AB%98%E7%9A%84%E6%A1%B6%20N%20%E8%B6%85%E8%BF%87%204%20%E5%90%8E%E5%87%A0%E4%B9%8E%E6%97%A0%E6%94%B6%E7%9B%8A%22%5D%0A%20%20end%0A%20%20subgraph%20MASK%5B%22%E6%8E%A9%E7%A0%81%EF%BC%9A%E6%82%AC%E5%B4%96%E5%9E%8B%22%5D%0A%20%20%20%20M1%5B%22%E7%BA%A6%E6%9D%9F%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20M2%5B%22%E5%90%88%E6%B3%95%E9%9B%86%E7%BC%A9%E5%88%B0%E9%AA%A8%E6%9E%B6%EF%BC%8C%E8%B4%A8%E9%87%8F%E8%B7%B3%E6%B0%B4%22%5D%0A%20%20end%0A%20%20subgraph%20CFG2%5B%22%E5%BC%95%E5%AF%BC%EF%BC%9A%E7%A6%BB%E6%B5%81%E5%BD%A2%E5%9E%8B%22%5D%0A%20%20%20%20C1%5B%22%E5%BC%95%E5%AF%BC%E6%9D%83%E9%87%8D%E5%8A%A0%E5%A4%A7%22%5D%20--%3E%20C2%5B%22%E5%A4%96%E6%8E%A8%E8%BF%87%E7%BA%BF%EF%BC%8C%E6%96%87%E6%9C%AC%E6%8E%89%E5%87%BA%E8%AF%AD%E8%A8%80%E6%B5%81%E5%BD%A2%22%5D%0A%20%20end%0A%20%20B2%20--%3E%20W%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E9%83%BD%E9%80%89%E5%9C%A8%E6%81%B6%E5%8C%96%E7%82%B9%E4%B9%8B%E5%89%8D%22%5D%0A%20%20M2%20--%3E%20W%0A%20%20C2%20--%3E%20W%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">这张图回答「为什么不能一路把旋钮拧到底」：三种旋钮的恶化形状不同——饱和是「加了白加」（浪费但不伤质量），悬崖与离流形是「加过头反而变差」（伤质量）。用数字感受悬崖：合法集从几万个候选 token 缩到几百个时，模型常常只能「在矮子里拔将军」，通顺度骤降。</span></p><p><span class="marginnote">曲线是会过期的资产：换模型、换分词器、换 schema 模板，曲线整体平移。每条曲线必须带版本戳与测量日期；没有版本戳的「文法 1.05× 成本、通过率 +18pt」不可复现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不同纵轴的曲线不能拼一张图；「人工偏好」做纵轴时样本量与评审协议必须先钉，否则曲线是噪声。成本只算 token 是漏账：打分器、沙箱、重试与修复率都要折进每请求成本，否则 BoN 与修复重的流量被系统性低估。<span class="marginnote">常见误区：初学者容易拿「生成的 token 数」当全部成本。一个 BoN=8 的请求真正烧掉的是 8 份 decode 加 1 次 RM 打分加可能的沙箱执行；漏掉后两项，账面上 BoN 显得比文法引导便宜，实际恰好相反——这也是团队「在错误的地方优化」的常见起点。</span>曲线回答「在给定模型上把推理算力花在哪」，不回答「要不要换更强的模型」——后者是另一条曲线的比较，前提是口径统一（Snell 等人的测试时计算权衡就是在这套坐标里比较宽度与深度的）。最后一课把课程收束成决策单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每旋钮一张成本倍率表：免费（采样、bias）、近免费（文法、投机）、线性（BoN、引导）。</li><li>质量度量一图一种：可执行验收优先于 RM、RM 优先于人工；换度量重画。</li><li>边际递减点各不同：BoN 饱和、掩码悬崖、引导离流形，工作点选在悬崖之前。</li><li>曲线按流量分桶使用，SLO 切可行域；工具调用的文法是可用性支出，不是质量支出。</li><li>成本入账含打分器、重试与修复；曲线带版本戳，换代重测。</li><li>出处：Snell et al., 2024；Pope et al., 2022；各旋钮口径见本课程与基础采样、服务成本各课。</li></ul>',6))])}const u=i(d,[["render",m]]);export{_ as __pageData,u as default};
